def has_close_elements(numbers, threshold):
    for i in range(len(numbers) - 1):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    deviations = [abs(x - mean) for x in numbers]
    return sum(deviations) / len(deviations)

def find_topmost_carpet(n, carpets, point):
    # Initialize a dictionary to map each carpet to its topmost point
    topmost_carpet = {}
    for carpet in carpets:
        topmost_carpet[carpet] = (carpet[0], carpet[1])

    # Iterate through each carpet, starting from the bottom
    for carpet in reversed(carpets):
        x, y = carpet[0], carpet[1]
        for i in range(2):
            size = carpet[i * 2 + 2]
            if x + size > point[0] and y + size > point[1]:
                topmost_carpet[carpet] = (x, y)
                break
            x += size
            y += size

    # Return the topmost carpet covering the point (x, y)
    for carpet, (a, b) in topmost_carpet.items():
        if a <= point[0] <= a + carpet[2] and b <= point[1] <= b + carpet[3]:
            return carpet
    return -1

def max_value_on_paths(N, grid_values):
    # Initialize a 2D array to store the maximum values for each position
    max_values = [[0] * N for _ in range(N)]

    # Initialize a 2D array to store the previous position for each position
    prev_positions = [[(0, 0)] * N for _ in range(N)]

    # Iterate through the grid values and update the maximum values and previous positions
    for x, y, value in grid_values:
        max_values[x][y] = value
        prev_positions[x][y] = (x, y)

    # Iterate through the grid in reverse order and update the maximum values and previous positions
    for x in range(N - 1, -1, -1):
        for y in range(N - 1, -1, -1):
            if x == N - 1 and y == N - 1:
                continue

            # Calculate the maximum value for the current position based on the previous positions
            max_value = max(max_values[x][y], max_values[x + 1][y], max_values[x][y + 1])
            max_values[x][y] = max_value

            # Update the previous position for the current position
            if max_value == max_values[x + 1][y]:
                prev_positions[x][y] = prev_positions[x + 1][y]
            elif max_value == max_values[x][y + 1]:
                prev_positions[x][y] = prev_positions[x][y + 1]
            else:
                prev_positions[x][y] = (x, y)

    # Calculate the maximum sum of values for the two paths
    max_sum = 0
    for x, y in prev_positions[0][0]:
        if x == N - 1 and y == N - 1:
            continue
        max_sum = max(max_sum, max_values[x][y])

    return max_sum

