def max_product(num_str, N, K):
    if K == 0:
        return 1
    max_product = 0
    for i in range(N):
        left_product = max_product(num_str[:i], i, K-1)
        right_product = max_product(num_str[i+1:], N-i-1, K-1)
        product = left_product * right_product
        max_product = max(max_product, product)
    return max_product

