def count_passing_ways(n: int, m: int) -> int:
    if n == 1 or m == 0:
        return 1
    if m == 1:
        return n
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(1, m + 1):
        for j in range(1, n):
            dp[i] += dp[i - 1]
            dp[i] %= 1000000007
    return dp[m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]):
    # Initialize the dp table with all values set to 0
    dp = [0] * (n + 1)

    # Sort the items by price in decreasing order
    items.sort(key=lambda x: x[0], reverse=True)

    # Loop through each item and compute the maximum happiness value
    for item in items:
        price, importance = item
        for i in range(1, n + 1):
            if i >= price:
                dp[i] = max(dp[i], dp[i - price] + importance)

    # Return the maximum happiness value
    return dp[n]

